-- RetailNova S.A. - SalesDB (SQL Server)
IF DB_ID('SalesDB') IS NULL CREATE DATABASE SalesDB;
GO
USE SalesDB;
GO
IF OBJECT_ID('Sales') IS NOT NULL DROP TABLE Sales;
IF OBJECT_ID('Customers') IS NOT NULL DROP TABLE Customers;
IF OBJECT_ID('Products') IS NOT NULL DROP TABLE Products;
IF OBJECT_ID('Branches') IS NOT NULL DROP TABLE Branches;
GO
CREATE TABLE Branches (branch_id INT PRIMARY KEY, city VARCHAR(50) NOT NULL, country VARCHAR(50) NOT NULL, region VARCHAR(50) NOT NULL);
GO
CREATE TABLE Products (product_id INT PRIMARY KEY, category VARCHAR(50) NOT NULL, brand VARCHAR(50) NOT NULL);
GO
CREATE TABLE Customers (customer_id INT PRIMARY KEY, name VARCHAR(100) NOT NULL, segment VARCHAR(30) NOT NULL, country VARCHAR(50) NOT NULL);
GO
CREATE TABLE Sales (sale_id INT PRIMARY KEY, date DATE NOT NULL, customer_id INT NOT NULL REFERENCES Customers(customer_id), product_id INT NOT NULL REFERENCES Products(product_id), quantity INT NOT NULL CHECK (quantity > 0), unit_price DECIMAL(10,2) NOT NULL, branch_id INT NOT NULL REFERENCES Branches(branch_id));
GO
SET NOCOUNT ON;
